package bench;
import java.util.concurrent.ConcurrentMap;
import org.openjdk.jmh.annotations.*;

@State(Scope.Thread)
public class WorkerState {
    ConcurrentMap<Integer, Integer> map;
    int cursor;

    @Setup(Level.Trial)
    public void setup() {
        map = MapFactory.mapForWorker();
    }
}

